// Author: MiYu. Typed parent/child hashtable values and handle-family reads for original custom-map scripts.
#include "session.h"
#include <algorithm>

namespace war3 {
void ScriptSession::bindHashtableNatives() {
    auto table=[this](jass::Value value){return std::get<std::shared_ptr<ScriptHashtable>>(object(value,NativeKind::Hashtable).state);};
    bind("InitHashtable","hashtable",{},[this](auto&,auto){return create(NativeKind::Hashtable);});
    auto store=[table](auto& vm,auto a,const std::string& type,bool result){auto state=table(a[0]);auto key=std::make_tuple(a[1].bits,a[2].bits,type);if(state->values.size()>=131072 && !state->values.contains(key))throw std::runtime_error("Hashtable value budget exceeded");state->values[key]=a[3];return result?vm.boolean(true):vm.nothing();};
    for(auto [suffix,type]:std::initializer_list<std::pair<const char*,const char*>>{{"Integer","integer"},{"Real","real"},{"Boolean","boolean"},{"Str","string"}}){
        bind((std::string("Save")+suffix).c_str(),std::string_view(type)=="string"?"boolean":"nothing",{"hashtable","integer","integer",type},[store,type](auto& vm,auto a){return store(vm,a,type,std::string_view(type)=="string");});
        bind((std::string("Load")+suffix).c_str(),type,{"hashtable","integer","integer"},[table,type](auto& vm,auto a){auto state=table(a[0]);auto found=state->values.find({a[1].bits,a[2].bits,type});return found==state->values.end()?jass::Value{vm.module().typeId(type),0,{}}:found->second;});
    }
    for(auto [suffix,type]:std::initializer_list<std::pair<const char*,const char*>>{{"Integer","integer"},{"Real","real"},{"Boolean","boolean"},{"String","string"},{"Handle","handle"}}){bind((std::string("HaveSaved")+suffix).c_str(),"boolean",{"hashtable","integer","integer"},[table,type](auto& vm,auto a){return vm.boolean(table(a[0])->values.contains({a[1].bits,a[2].bits,type}));});bind((std::string("RemoveSaved")+suffix).c_str(),"nothing",{"hashtable","integer","integer"},[table,type](auto& vm,auto a){table(a[0])->values.erase({a[1].bits,a[2].bits,type});return vm.nothing();});}
    auto& module=runtime_.module();for(size_t i=0;i<module.program().functions().size();++i){auto& source=module.program().functions()[i];if(!source.native || !source.name.ends_with("Handle"))continue;auto& signature=module.functions()[i];if(source.name.starts_with("Save") && signature.parameters.size()==4 && module.type(signature.parameters[0]).name=="hashtable"){auto type=module.type(signature.parameters[3]).name;if(module.type(signature.parameters[3]).category!=jass::Category::Handle)continue;bind(source.name.c_str(),"boolean",{"hashtable","integer","integer",type.c_str()},[store](auto& vm,auto a){return store(vm,a,"handle",true);});}
        else if(source.name.starts_with("Load") && signature.parameters.size()==3 && module.type(signature.parameters[0]).name=="hashtable" && module.type(signature.result).category==jass::Category::Handle){auto type=module.type(signature.result).name;bind(source.name.c_str(),type.c_str(),{"hashtable","integer","integer"},[this,table,type](auto& vm,auto a){auto state=table(a[0]);auto found=state->values.find({a[1].bits,a[2].bits,"handle"});if(found==state->values.end())return vm.handle(type,0);auto value=found->second;auto wanted=vm.module().typeId(type);if(vm.module().assignable(wanted,value.type))return vm.handle(type,value.bits);if(value.bits>=handleBase && value.bits-handleBase<objects_.size()){auto kind=objects_[value.bits-handleBase].kind;const char* dynamic=nullptr;switch(kind){case NativeKind::TextTag:dynamic="texttag";break;case NativeKind::Multiboard:dynamic="multiboard";break;case NativeKind::MultiboardItem:dynamic="multiboarditem";break;case NativeKind::Leaderboard:dynamic="leaderboard";break;case NativeKind::Lightning:dynamic="lightning";break;case NativeKind::Effect:dynamic="effect";break;case NativeKind::Ability:dynamic="ability";break;case NativeKind::Dialog:dynamic="dialog";break;case NativeKind::Button:dynamic="button";break;case NativeKind::DefeatCondition:dynamic="defeatcondition";break;case NativeKind::Destructable:dynamic="destructable";break;case NativeKind::Unit:dynamic="unit";break;case NativeKind::Item:dynamic="item";break;case NativeKind::Player:dynamic="player";break;case NativeKind::Group:dynamic="group";break;case NativeKind::Timer:dynamic="timer";break;case NativeKind::Trigger:dynamic="trigger";break;case NativeKind::Location:dynamic="location";break;case NativeKind::Rect:dynamic="rect";break;case NativeKind::Sound:dynamic="sound";break;case NativeKind::Weather:dynamic="weathereffect";break;case NativeKind::Force:dynamic="force";break;case NativeKind::Boolean:dynamic="boolexpr";break;case NativeKind::Action:dynamic="triggeraction";break;case NativeKind::Condition:dynamic="triggercondition";break;case NativeKind::Event:dynamic="event";break;case NativeKind::TimerDialog:dynamic="timerdialog";break;case NativeKind::Region:dynamic="region";break;case NativeKind::Fog:dynamic="fogmodifier";break;case NativeKind::Cache:dynamic="gamecache";break;case NativeKind::Hashtable:dynamic="hashtable";break;default:break;}if(dynamic && vm.module().assignable(wanted,vm.module().typeId(dynamic)))return vm.handle(type,value.bits);}return vm.handle(type,0);});}}
    bind("FlushChildHashtable","nothing",{"hashtable","integer"},[table](auto& vm,auto a){auto state=table(a[0]);std::erase_if(state->values,[&](auto& value){return std::get<0>(value.first)==a[1].bits;});return vm.nothing();});
    bind("FlushParentHashtable","nothing",{"hashtable"},[table](auto& vm,auto a){table(a[0])->values.clear();return vm.nothing();});
}
}
